create table if not exists public.purchase_document_reviews (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, venue_id uuid not null references public.venues(id) on delete cascade, file_name text not null, content_type text not null, object_path text, extraction jsonb not null, status text not null default 'needs_review' check (status in ('needs_review','approved','rejected')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now());
alter table public.purchase_document_reviews enable row level security;
create policy purchase_document_reviews_read on public.purchase_document_reviews for select to authenticated using (public.has_tenant_role(tenant_id, array['owner','manager','accountant']::public.tenant_role[]));
create policy purchase_document_reviews_write on public.purchase_document_reviews for all to authenticated using (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[])) with check (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[]));
